<?php
$metrics=[['Published content','book',(int)$a->db->value("SELECT COUNT(*) FROM cy_contents WHERE status='published' AND publish_at<=?",[time()]),'Visible to eligible visitors'],['Community members','users',$a->memberCount(),'Active accounts'],['Paid orders','box',(int)$a->db->value("SELECT COUNT(*) FROM cy_orders WHERE status='paid'"),'All successfully settled orders'],['Awaiting review','shield',(int)$a->db->value("SELECT COUNT(*) FROM cy_contents WHERE status='pending'")+(int)$a->db->value("SELECT COUNT(*) FROM cy_comments WHERE status='pending'"),'Content and comments']];
$days=[];for($i=6;$i>=0;$i--){$start=strtotime(date('Y-m-d').' -'.$i.' days');$days[]=['date'=>date('m.d',$start),'count'=>(int)$a->db->value("SELECT COUNT(*) FROM cy_orders WHERE status='paid' AND paid_at>=? AND paid_at<?",[$start,$start+86400])];}$max=max(1,max(array_column($days,'count')));
?>
<div class="admin-title"><div><span class="eyebrow">A CLEAR VIEW OF YOUR ISLAND</span><h1><?= t('Good ideas start here.') ?></h1><p><?= t('Welcome back') ?>, <?= e($me['display_name']) ?>. <?= t('Here is what is happening in your community.') ?></p></div><a class="btn" href="<?= e(au('edit_content')) ?>"><?= icon('plus') ?><?= t('Create content') ?></a></div><div class="metric-grid section"><?php foreach ($metrics as $metric): ?><article class="metric-card panel glass"><div class="metric-label"><span><?= t($metric[0]) ?></span><span class="metric-icon"><?= icon($metric[1]) ?></span></div><strong><?= number_format($metric[2]) ?></strong><small><?= t($metric[3]) ?></small></article><?php endforeach ?></div><div class="two-column section"><section class="panel glass"><div class="section-heading"><div><h2><?= t('The rhythm of your community') ?></h2><p class="subtitle"><?= t('Settled orders in the last seven days') ?></p></div><span class="pill soft">7 <?= t('days') ?></span></div><div class="dashboard-chart" role="img" aria-label="<?= t('Settled order count by day') ?>"><?php foreach ($days as $day): ?><div class="chart-column"><span><?= $day['count'] ?></span><div class="chart-track"><i style="height:<?= max(2,(int)round($day['count']/$max*100)) ?>%"></i></div><small><?= e($day['date']) ?></small></div><?php endforeach ?></div><p class="hint"><?= t('Counts include purchases, membership, exchanges and top-ups. They are not cash revenue.') ?></p></section><section class="panel dashboard-checklist"><div class="section-heading"><h2><?= t('Ready for your next chapter?') ?></h2><?= icon('sparkles') ?></div><?php $checks=[['Configure your identity','Site name, contact and legal notices','site','settings'],['Make it feel like you','Themes, glass and motion curves','appearance','settings'],['Connect a payment provider','Merchant keys and callback validation','epay','settings'],['Check your environment','Runtime, database and HTTPS','','system']];foreach($checks as $check): ?><a class="setup-item" href="<?= e(au($check[3],$check[2]?['group'=>$check[2]]:[])) ?>"><span class="setup-dot"><?= icon('check') ?></span><div class="grow"><strong><?= t($check[0]) ?></strong><small><?= t($check[1]) ?></small></div><?= icon('chevron') ?></a><?php endforeach ?><div class="alert info"><?= t('Sample content is editable and removable. No visitor counts or sales are fabricated.') ?></div></section></div><div class="two-column"><section class="panel glass"><div class="section-heading"><h2><?= t('Fresh from your desk') ?></h2><a class="text-link" href="<?= e(au('contents')) ?>"><?= t('Manage') ?><?= icon('arrow') ?></a></div><?php foreach ($a->db->all('SELECT id,title,kind,status,updated_at FROM cy_contents ORDER BY updated_at DESC,id DESC LIMIT 5') as $entry): ?><a class="recent-content" href="<?= e(au('edit_content',['id'=>$entry['id']])) ?>"><span class="quick-icon"><?= icon($entry['kind']==='product'?'box':'book') ?></span><div class="grow"><strong><?= e($entry['title']) ?></strong><small><?= dt((int)$entry['updated_at'],'m.d H:i') ?></small></div><span class="pill <?= e($entry['status']) ?>"><?= t($entry['status']) ?></span></a><?php endforeach ?></section><section class="panel glass"><div class="section-heading"><h2><?= t('A traceable workspace') ?></h2><a class="text-link" href="<?= e(au('logs')) ?>"><?= t('View logs') ?><?= icon('arrow') ?></a></div><?php foreach ($a->db->all('SELECT * FROM cy_audit ORDER BY id DESC LIMIT 6') as $row): ?><div class="audit-item"><span class="audit-dot"></span><div class="grow"><strong><?= t($row['action']) ?></strong><small>#<?= (int)$row['actor_id'] ?> &middot; <?= e($row['target']) ?></small></div><time><?= dt((int)$row['created_at'],'H:i') ?></time></div><?php endforeach ?></section></div>
